import React, { useEffect, useMemo, useState } from 'react';
import { Alert, Badge, Card, Col, Container, Form, InputGroup, ListGroup, Row, Spinner } from 'react-bootstrap';
import PlotPieA from './occupy.jsx';
import PlotPieB from './occupy-company.jsx';
import PlotPersonaComp from './persona-comp.jsx';
import PlotPersonaTopic from './persona-topic.jsx';
import PlotBarChartA from './trend-topix.jsx';
import PlotBarChartB from './trend-comp.jsx';
import ProposedVisualize from './go-anywhere.jsx';

const MAX_VISIBLE_DOCS = 120;
const MAX_SUBPANEL_RANK = 20;
const DEFAULT_VISIBLE_RANGES = ['1-5', '11-15'];

const Content = ({
  plot,
  visualType,
  topic,
  company,
  resetApply,
  patentPanelWidth = 220,
  topicLabelMap,
}) => {
  const [clickData, setClickData] = useState();
  const [clickCompanyData, setClickCompanyData] = useState();
  const [topicDocs, setTopicDocs] = useState([]);
  const [docsLoading, setDocsLoading] = useState(false);
  const [docsError, setDocsError] = useState('');
  const [docsSearchTerm, setDocsSearchTerm] = useState('');
  const [isRangeSettingOpen, setIsRangeSettingOpen] = useState(false);
  const [visibleRankRanges, setVisibleRankRanges] = useState(DEFAULT_VISIBLE_RANGES);
  const activeTopicId = String(topic?.[0] ?? '');

  const handlePieChartClick = (data) => {
    console.log('クリックされたデータ:', data);
    setClickData(data);
  };

  const handlePersonaClick = (data) => {
    console.log('クリックされたデータ:', data);
    setClickCompanyData(data);
  };

  useEffect(() => {
    const fetchTopicDocs = async () => {
      if (!activeTopicId) {
        setTopicDocs([]);
        return;
      }

      setDocsLoading(true);
      setDocsError('');
      try {
        const response = await fetch(
          `${process.env.PUBLIC_URL}/data/visualize_data/patents/topic/${activeTopicId}.json`,
          { cache: 'force-cache' }
        );
        if (!response.ok) {
          throw new Error(`HTTP ${response.status}`);
        }
        const data = await response.json();
        // 文献データが不完全でも描画を壊さないように正規化
        const normalizedDocs = Array.isArray(data)
          ? data
              .filter((doc) => doc && typeof doc === 'object')
              .map((doc) => ({
                number: typeof doc.number === 'string' ? doc.number : '',
                title: typeof doc.title === 'string' ? doc.title : '',
                inventors: Array.isArray(doc.inventors) ? doc.inventors : [],
              }))
          : [];
        setTopicDocs(normalizedDocs);
      } catch (error) {
        setTopicDocs([]);
        setDocsError(`TOPIC ${activeTopicId} の文献データが未作成または読み込み不可です`);
        console.error('文献リストの読み込み失敗:', error);
      } finally {
        setDocsLoading(false);
      }
    };

    fetchTopicDocs();
  }, [activeTopicId]);

  const docsFiltered = useMemo(() => {
    const term = docsSearchTerm.trim().toLowerCase();
    const base = term
      ? topicDocs.filter((doc) => {
          const inventorText = Array.isArray(doc.inventors) ? doc.inventors.join(' ') : '';
          return (
            (doc.title || '').toLowerCase().includes(term) ||
            (doc.number || '').toLowerCase().includes(term) ||
            inventorText.toLowerCase().includes(term)
          );
        })
      : topicDocs;

    return base.slice(0, MAX_VISIBLE_DOCS);
  }, [topicDocs, docsSearchTerm]);

  const docsTopRanked = useMemo(
    () => docsFiltered.slice(0, MAX_SUBPANEL_RANK),
    [docsFiltered]
  );

  const docsForDisplay = useMemo(() => {
    const rangeToIndices = {
      '1-5': [0, 4],
      '6-10': [5, 9],
      '11-15': [10, 14],
      '16-20': [15, 19],
    };

    if (visibleRankRanges.length === 0) {
      return [];
    }

    const selectedIndices = new Set();
    visibleRankRanges.forEach((rangeKey) => {
      const range = rangeToIndices[rangeKey];
      if (!range) {
        return;
      }
      for (let i = range[0]; i <= range[1]; i += 1) {
        selectedIndices.add(i);
      }
    });

    return docsTopRanked
      .map((doc, idx) => ({ doc, rank: idx + 1 }))
      .filter((item) => selectedIndices.has(item.rank - 1));
  }, [docsTopRanked, visibleRankRanges]);

  const toggleVisibleRange = (rangeKey) => {
    setVisibleRankRanges((prev) =>
      prev.includes(rangeKey) ? prev.filter((item) => item !== rangeKey) : [...prev, rangeKey]
    );
  };

  return (
    <Container fluid className="bg-light py-1" style={{ height: '100vh', overflow: 'hidden' }}>
      <div style={{ display: 'flex', gap: '8px', height: '100%' }}>
        <div style={{ width: `calc(100% - ${patentPanelWidth}px)`, minWidth: 0 }}>
          <div className="bg-light py-1" style={{ height: '100%', display: 'flex', flexDirection: 'column', gap: '8px' }}>
            <div style={{ height: '44vh', minHeight: 0 }}>
              {visualType === 'one-topic' ? (
                <PlotPersonaTopic
                  update={plot}
                  visualType={visualType}
                  topic={topic}
                  company={company}
                  topicLabelMap={topicLabelMap}
                  onRendered={resetApply}
                  onClickData={handlePersonaClick}
                  layout={{
                    title: 'ペルソナの可視化',
                    width: '100%',
                    height: '100%',
                  }}
                  config={{ responsive: true }}
                  style={{ width: '100%', height: '100%' }}
                  className="bg-light"
                />
              ) : visualType === 'one-comp' ? (
                <PlotPersonaComp
                  update={plot}
                  visualType={visualType}
                  topic={topic}
                  company={company}
                  topicLabelMap={topicLabelMap}
                  onRendered={resetApply}
                  layout={{
                    title: 'ペルソナの可視化',
                    width: '100%',
                    height: '100%',
                  }}
                  config={{ responsive: true }}
                  style={{ width: '100%', height: '100%' }}
                  className="bg-light"
                />
              ) : (
                <div>該当する表示がありません</div>
              )}
            </div>

            <Row className="g-2 mt-0 flex-grow-1" style={{ minHeight: 0 }}>
              <Col md={6} style={{ display: 'flex', minHeight: 0 }}>
                <Card className="w-100" style={{ height: '100%' }}>
                  <Card.Body className="p-2">
                    {visualType === 'one-topic' ? (
                      <PlotPieA
                        update={plot}
                        visualType={visualType}
                        topic={topic}
                        company={company}
                        topicLabelMap={topicLabelMap}
                        onRendered={resetApply}
                        layout={{
                          title: '注目企業の業界に対する占有率',
                          width: '100%',
                          height: '80%',
                        }}
                        className="bg-light"
                      />
                    ) : visualType === 'one-comp' ? (
                      <PlotPieB
                        update={plot}
                        visualType={visualType}
                        topic={topic}
                        company={company}
                        topicLabelMap={topicLabelMap}
                        onRendered={resetApply}
                        onClickData={handlePieChartClick}
                        layout={{
                          title: '注目企業の業界に対する占有率',
                          width: '100%',
                          height: '80%',
                        }}
                        className="bg-light"
                      />
                    ) : (
                      <div>該当する表示がありません</div>
                    )}
                  </Card.Body>
                </Card>
              </Col>
              <Col md={6} style={{ display: 'flex', minHeight: 0 }}>
                <Card className="w-100" style={{ height: '100%' }}>
                  <Card.Body className="p-2">
                    {visualType === 'one-topic' ? (
                      <PlotBarChartA
                        update={plot}
                        visualType={visualType}
                        topic={topic}
                        onRendered={resetApply}
                        data={[]}
                        layout={{
                          title: 'Fタームの分布',
                          width: '100%',
                          height: '80%',
                        }}
                        className="bg-light"
                      />
                    ) : (
                      <PlotBarChartB
                        update={plot}
                        visualType={visualType}
                        topic={topic}
                        company={company}
                        clickdata={clickData}
                        onRendered={resetApply}
                        data={[]}
                        layout={{
                          title: 'Fタームの分布',
                          width: '100%',
                          height: '80%',
                        }}
                        className="bg-light"
                      />
                    )}
                  </Card.Body>
                </Card>
              </Col>
            </Row>
          </div>
        </div>

        <div style={{ width: `${patentPanelWidth}px`, minWidth: `${patentPanelWidth}px`, maxWidth: '40vw' }}>
          <Card style={{ height: '100%' }} className="border-info-subtle">
            <Card.Body className="py-2 px-2 d-flex flex-column">
              <div style={{ position: 'sticky', top: 0, zIndex: 2, backgroundColor: 'white' }}>
                <div className="d-flex justify-content-between align-items-center mb-1">
                  <div className="text-muted" style={{ fontSize: '0.72rem' }}>TOPIC別 文献</div>
                  <Badge bg="secondary">{topicDocs.length}</Badge>
                </div>
                <div className="text-muted mb-1" style={{ fontSize: '0.72rem' }}>TOPIC {activeTopicId || '-'}</div>

                <InputGroup size="sm" className="mb-1">
                  <Form.Control
                    placeholder="文献を検索"
                    value={docsSearchTerm}
                    onChange={(e) => setDocsSearchTerm(e.target.value)}
                    style={{ fontSize: '0.78rem', padding: '0.2rem 0.45rem' }}
                  />
                </InputGroup>

                <div className="d-flex justify-content-end mb-1">
                  <button
                    type="button"
                    className="btn btn-outline-secondary btn-sm"
                    onClick={() => setIsRangeSettingOpen((prev) => !prev)}
                  >
                    設定
                  </button>
                </div>
              </div>

              {isRangeSettingOpen && (
                <div className="border rounded p-2 mb-2 bg-light">
                  <div className="text-muted mb-1" style={{ fontSize: '0.72rem' }}>表示範囲（上位20位から選択）</div>
                  <div className="d-flex flex-wrap gap-2">
                    {['1-5', '6-10', '11-15', '16-20'].map((rangeKey) => (
                      <Form.Check
                        key={rangeKey}
                        type="checkbox"
                        id={`rank-range-${rangeKey}`}
                        label={`${rangeKey}位`}
                        checked={visibleRankRanges.includes(rangeKey)}
                        onChange={() => toggleVisibleRange(rangeKey)}
                        className="small"
                      />
                    ))}
                  </div>
                  <div className="mt-2 d-flex gap-2">
                    <button
                      type="button"
                      className="btn btn-outline-primary btn-sm"
                      onClick={() => setVisibleRankRanges(DEFAULT_VISIBLE_RANGES)}
                    >
                      デフォルト
                    </button>
                    <button
                      type="button"
                      className="btn btn-outline-secondary btn-sm"
                      onClick={() => setVisibleRankRanges(['1-5', '6-10', '11-15', '16-20'])}
                    >
                      1-20を全表示
                    </button>
                  </div>
                </div>
              )}

              {docsLoading && (
                <div className="text-muted" style={{ fontSize: '0.72rem' }}>
                  <Spinner size="sm" animation="border" className="me-2" />
                  読み込み中...
                </div>
              )}

              {!docsLoading && docsError && (
                <Alert variant="warning" className="mb-0 py-1 px-2" style={{ fontSize: '0.72rem' }}>
                  {docsError}
                </Alert>
              )}

              {!docsLoading && !docsError && (
                <>
                  <div className="text-muted mb-1" style={{ fontSize: '0.72rem' }}>
                    表示: {docsForDisplay.length} 件（検索結果上位20位から）
                  </div>
                  <ListGroup style={{ overflowY: 'auto', flex: 1, minHeight: 0 }}>
                    {docsForDisplay.map(({ doc, rank }) => (
                      <ListGroup.Item key={`${doc.number || 'doc'}-${rank}`} className="py-1 px-2">
                        <div className="fw-bold" style={{ fontSize: '0.76rem' }}>{rank}位: {doc.number}</div>
                        <div style={{ fontSize: '0.72rem' }}>{doc.title || '(タイトルなし)'}</div>
                      </ListGroup.Item>
                    ))}
                    {docsForDisplay.length === 0 && (
                      <ListGroup.Item className="text-muted" style={{ fontSize: '0.72rem' }}>
                        該当する文献はありません（設定の表示範囲もご確認ください）
                      </ListGroup.Item>
                    )}
                  </ListGroup>
                </>
              )}
            </Card.Body>
          </Card>
        </div>
      </div>

      {visualType === 'one-topic' && clickCompanyData && (
        <Row>
          <Col>
            <ProposedVisualize
              topic={topic}
              clickData={clickCompanyData}
              layout={{
                title: '任意の位置へ移動するための提案',
                width: '100%',
                height: '80%',
              }}
              className="bg-light"
            />
          </Col>
        </Row>
      )}
    </Container>
  );
};

export default Content;

